create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','admin','manager','member','viewer');
create type public.customer_status as enum ('active','trial','past_due','canceled');
create type public.transaction_status as enum ('approved','pending','failed','refunded');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', avatar_url text, created_at timestamptz not null default now());
create table public.workspaces(id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, owner_id uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.workspace_members(workspace_id uuid references public.workspaces(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role public.member_role not null default 'member', joined_at timestamptz not null default now(), primary key(workspace_id,user_id));
create table public.plans(id text primary key, name text not null, price_monthly numeric(12,2) not null check(price_monthly>=0), features jsonb not null default '[]');
create table public.customers(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null, email text not null, company text, plan_id text references public.plans(id), status public.customer_status not null default 'trial', mrr numeric(12,2) not null default 0 check(mrr>=0), last_activity_at timestamptz, created_at timestamptz not null default now(), unique(workspace_id,email));
create table public.subscriptions(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, customer_id uuid not null references public.customers(id) on delete cascade, plan_id text not null references public.plans(id), status text not null check(status in ('active','trialing','past_due','canceled')), current_period_end timestamptz, amount numeric(12,2) not null check(amount>=0), created_at timestamptz not null default now());
create table public.transactions(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, customer_id uuid references public.customers(id) on delete set null, amount numeric(12,2) not null check(amount>=0), method text not null, status public.transaction_status not null, processed_at timestamptz not null default now());
create table public.activities(id bigint generated always as identity primary key, workspace_id uuid not null references public.workspaces(id) on delete cascade, actor_id uuid references auth.users(id) on delete set null, customer_id uuid references public.customers(id) on delete cascade, kind text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.notifications(id bigint generated always as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, title text not null, read_at timestamptz, created_at timestamptz not null default now());
create index customers_workspace_idx on public.customers(workspace_id); create index transactions_workspace_date_idx on public.transactions(workspace_id,processed_at desc); create index activities_workspace_date_idx on public.activities(workspace_id,created_at desc);
create function public.is_workspace_member(target uuid) returns boolean language sql stable security invoker set search_path='' as $$ select exists(select 1 from public.workspace_members m where m.workspace_id=target and m.user_id=(select auth.uid())) $$;
alter table public.profiles enable row level security; alter table public.workspaces enable row level security; alter table public.workspace_members enable row level security; alter table public.plans enable row level security; alter table public.customers enable row level security; alter table public.subscriptions enable row level security; alter table public.transactions enable row level security; alter table public.activities enable row level security; alter table public.notifications enable row level security;
create policy "profiles_select_self" on public.profiles for select to authenticated using(id=(select auth.uid())); create policy "profiles_update_self" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy "plans_read" on public.plans for select to authenticated using(true);
create policy "workspace_member_read" on public.workspaces for select to authenticated using(public.is_workspace_member(id));
create policy "membership_read" on public.workspace_members for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "customers_member_all" on public.customers for all to authenticated using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy "subscriptions_member_all" on public.subscriptions for all to authenticated using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy "transactions_member_all" on public.transactions for all to authenticated using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy "activities_member_all" on public.activities for all to authenticated using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy "notifications_self" on public.notifications for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
insert into public.plans(id,name,price_monthly,features) values ('free','Free',0,'["2 seats","Basic analytics"]'),('starter','Starter',19,'["10 seats","Email support"]'),('pro','Pro',49,'["25 seats","Advanced analytics"]'),('business','Business',129,'["Unlimited seats","Priority support"]');
